import math
from collections import defaultdict

def prime_factorization(n):
    factors = defaultdict(int)
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] += 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] += 1
    return factors

def phi(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    result = n
    for p in factors:
        result = result * (p - 1) // p
    return result

def order(a, n):
    if math.gcd(a, n) != 1:
        # This should not happen based on the formula usage (m' must be coprime to 3 if 3 is the base)
        # but let's handle it defensively.
        return 0 

    phi_n = phi(n)

    # Find prime factors of phi(n)
    factors_phi = prime_factorization(phi_n)
    primes = list(factors_phi.keys())

    # Check divisors of phi(n)
    order_candidate = phi_n

    for p in primes:
        while order_candidate % p == 0:
            # Check if order_candidate / p is still the order
            if pow(a, order_candidate // p, n) == 1:
                order_candidate //= p
            else:
                break
    return order_candidate

def count_cycles(m):
    if m <= 1:
        return 0

    # C(m) = sum_{m' | m, m' > 1} phi(m') / order_{m'}(3)

    divisors = []
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divisors.append(i)
            if i * i != m:
                divisors.append(m // i)

    total_cycles = 0
    for m_prime in divisors:
        if m_prime > 1:
            # We must check if gcd(3, m') == 1. 
            # Since m is not divisible by 3, any divisor m' of m is not divisible by 3.
            # So gcd(3, m') is guaranteed to be 1.
            L = order(3, m_prime)
            if L == 0: # Should not happen if m_prime > 1 and 3 is coprime to m_prime
                 print(f"Warning: order(3, {m_prime}) is 0.")
                 continue
            total_cycles += phi(m_prime) // L

    return total_cycles

